-- name: kubernetes_pf__preflight_test_evidence :one
SELECT invocation.safe_error_code,(SELECT count(*) FROM control_plane.kubernetes_execution_effects effect JOIN control_plane.kubernetes_execution_children child ON child.id=effect.child_id JOIN control_plane.kubernetes_execution_plans plan ON plan.id=child.plan_id WHERE plan.invocation_id=invocation.id),(SELECT count(*) FROM control_plane.kubernetes_execution_streams stream JOIN control_plane.kubernetes_execution_effects effect ON effect.id=stream.effect_id JOIN control_plane.kubernetes_execution_children child ON child.id=effect.child_id JOIN control_plane.kubernetes_execution_plans plan ON plan.id=child.plan_id WHERE plan.invocation_id=invocation.id) FROM control_plane.integration_invocations invocation WHERE invocation.ref=$1;
